CREATE TABLE IF NOT EXISTS local_quotes (id text PRIMARY KEY, owner_id text, source_amount numeric(30,2) NOT NULL, destination_amount numeric(30,7) NOT NULL, fee_amount numeric(30,2) NOT NULL, rate numeric(30,7) NOT NULL, purpose text NOT NULL, expires_at timestamptz NOT NULL, used_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS local_routes (id text PRIMARY KEY, quote_id text NOT NULL REFERENCES local_quotes(id), owner_id text NOT NULL, reference text NOT NULL, status text NOT NULL, version bigint NOT NULL DEFAULT 1, transaction_hash text UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS local_route_events (id text PRIMARY KEY, route_id text NOT NULL REFERENCES local_routes(id), status text NOT NULL, note text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS local_route_idempotency (owner_id text NOT NULL, idempotency_key text NOT NULL, request_digest text NOT NULL, route_id text NOT NULL REFERENCES local_routes(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(owner_id,idempotency_key));
